    inline constexpr const Instance* FindInstance(uint32_t instanceId)
    {
        for (auto const& inst : kInstances)
            if (inst.instance_id == instanceId)
                return &inst;
        return nullptr;
    }

    inline constexpr const Continent* FindContinentByKey(std::string_view key)
    {
        for (auto const& c : kContinents)
            if (c.key == key)
                return &c;
        return nullptr;
    }

